insert into public.lesson_content (id, lesson_id, content_type, korean_text, english_text, romanization, audio_url, metadata, order_index)
values
  ('lesson-greetings-hello-introduction-0', 'lesson-greetings-hello', 'introduction', null, 'Korean has one greeting that works almost everywhere — morning, evening, shop or office. You will hear it a hundred times a day in Seoul.', null, null, '{"heading":"Hello & Goodbye"}'::jsonb, 0),
  ('lesson-greetings-hello-vocabulary-1', 'lesson-greetings-hello', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-annyeong"}'::jsonb, 1),
  ('lesson-greetings-hello-vocabulary-2', 'lesson-greetings-hello', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-annyeonghi"}'::jsonb, 2),
  ('lesson-greetings-hello-vocabulary-3', 'lesson-greetings-hello', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-annyeonghi-gyeseyo"}'::jsonb, 3),
  ('lesson-greetings-hello-vocabulary-4', 'lesson-greetings-hello', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-mannaseo"}'::jsonb, 4),
  ('lesson-greetings-hello-expression-5', 'lesson-greetings-hello', 'expression', '안녕하세요.', 'Hello.', 'annyeonghaseyo.', null, '{"note":"Polite and safe with anyone."}'::jsonb, 5),
  ('lesson-greetings-hello-expression-6', 'lesson-greetings-hello', 'expression', '만나서 반가워요.', 'Nice to meet you.', 'mannaseo bangawoyo.', null, null, 6),
  ('lesson-greetings-hello-expression-7', 'lesson-greetings-hello', 'expression', '안녕히 가세요.', 'Goodbye — to the person leaving.', 'annyeonghi gaseyo.', null, null, 7),
  ('lesson-greetings-hello-expression-8', 'lesson-greetings-hello', 'expression', '안녕히 계세요.', 'Goodbye — to the person staying.', 'annyeonghi gyeseyo.', null, null, 8),
  ('lesson-greetings-hello-listening-9', 'lesson-greetings-hello', 'listening', '안녕하세요! 오랜만이에요.', 'Hello! Long time no see.', 'annyeonghaseyo! oraenmanieyo.', null, null, 9),
  ('lesson-greetings-hello-speaking-10', 'lesson-greetings-hello', 'speaking', '안녕하세요. 만나서 반가워요.', 'Hello. Nice to meet you.', 'annyeonghaseyo. mannaseo bangawoyo.', null, null, 10),
  ('lesson-greetings-hello-summary-11', 'lesson-greetings-hello', 'summary', null, null, null, null, '{"points":["안녕하세요 works as hello at any time of day.","Leaving? The person staying says 안녕히 가세요.","Staying? You say 안녕히 계세요 to them."]}'::jsonb, 11),
  ('lesson-greetings-yesno-introduction-0', 'lesson-greetings-yesno', 'introduction', null, 'Korean 네 is closer to "I hear you" than a hard yes. You will use it constantly as a listening signal.', null, null, '{"heading":"Yes & No"}'::jsonb, 0),
  ('lesson-greetings-yesno-vocabulary-1', 'lesson-greetings-yesno', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-ne"}'::jsonb, 1),
  ('lesson-greetings-yesno-vocabulary-2', 'lesson-greetings-yesno', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-aniyo"}'::jsonb, 2),
  ('lesson-greetings-yesno-vocabulary-3', 'lesson-greetings-yesno', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-gwaenchanayo"}'::jsonb, 3),
  ('lesson-greetings-yesno-vocabulary-4', 'lesson-greetings-yesno', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-joayo"}'::jsonb, 4),
  ('lesson-greetings-yesno-expression-5', 'lesson-greetings-yesno', 'expression', '네, 맞아요.', 'Yes, that''s right.', 'ne, majayo.', null, null, 5),
  ('lesson-greetings-yesno-expression-6', 'lesson-greetings-yesno', 'expression', '아니요, 괜찮아요.', 'No, I''m fine.', 'aniyo, gwaenchanayo.', null, null, 6),
  ('lesson-greetings-yesno-expression-7', 'lesson-greetings-yesno', 'expression', '네, 좋아요.', 'Yes, sounds good.', 'ne, joayo.', null, null, 7),
  ('lesson-greetings-yesno-listening-8', 'lesson-greetings-yesno', 'listening', '봉투 필요하세요? — 아니요, 괜찮아요.', 'Do you need a bag? — No, I’m fine.', 'bongtu piryohaseyo? — aniyo, gwaenchanayo.', null, null, 8),
  ('lesson-greetings-yesno-speaking-9', 'lesson-greetings-yesno', 'speaking', '네, 괜찮아요.', 'Yes, it''s fine.', 'ne, gwaenchanayo.', null, null, 9),
  ('lesson-greetings-yesno-summary-10', 'lesson-greetings-yesno', 'summary', null, null, null, null, '{"points":["네 = yes / I follow you.","아니요 = no.","괜찮아요 politely declines anything."]}'::jsonb, 10),
  ('lesson-greetings-thanks-introduction-0', 'lesson-greetings-thanks', 'introduction', null, 'There are two thank-yous you need: one formal, one warm. Getting the difference right makes you sound thoughtful.', null, null, '{"heading":"Thank You"}'::jsonb, 0),
  ('lesson-greetings-thanks-vocabulary-1', 'lesson-greetings-thanks', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-gamsa"}'::jsonb, 1),
  ('lesson-greetings-thanks-vocabulary-2', 'lesson-greetings-thanks', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-gomawo"}'::jsonb, 2),
  ('lesson-greetings-thanks-vocabulary-3', 'lesson-greetings-thanks', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-cheonmaneyo"}'::jsonb, 3),
  ('lesson-greetings-thanks-vocabulary-4', 'lesson-greetings-thanks', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-joesonghamnida"}'::jsonb, 4),
  ('lesson-greetings-thanks-expression-5', 'lesson-greetings-thanks', 'expression', '감사합니다.', 'Thank you.', 'gamsahamnida.', null, '{"note":"Formal — staff, elders, work."}'::jsonb, 5),
  ('lesson-greetings-thanks-expression-6', 'lesson-greetings-thanks', 'expression', '고마워요.', 'Thanks.', 'gomawoyo.', null, '{"note":"Warm — friends, peers."}'::jsonb, 6),
  ('lesson-greetings-thanks-expression-7', 'lesson-greetings-thanks', 'expression', '천만에요.', 'You''re welcome.', 'cheonmaneyo.', null, null, 7),
  ('lesson-greetings-thanks-listening-8', 'lesson-greetings-thanks', 'listening', '도와주셔서 감사합니다.', 'Thank you for your help.', 'dowajusyeoseo gamsahamnida.', null, null, 8),
  ('lesson-greetings-thanks-speaking-9', 'lesson-greetings-thanks', 'speaking', '정말 감사합니다.', 'Thank you so much.', 'jeongmal gamsahamnida.', null, null, 9),
  ('lesson-greetings-thanks-summary-10', 'lesson-greetings-thanks', 'summary', null, null, null, null, '{"points":["감사합니다 is never wrong.","고마워요 is for people close to you.","죄송합니다 is sorry, not thanks."]}'::jsonb, 10),
  ('lesson-greetings-intro-introduction-0', 'lesson-greetings-intro', 'introduction', null, 'Three sentences and you can introduce yourself to anyone in Korea: name, country, and a friendly closer.', null, null, '{"heading":"Introducing Yourself"}'::jsonb, 0),
  ('lesson-greetings-intro-vocabulary-1', 'lesson-greetings-intro', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-jeoneun"}'::jsonb, 1),
  ('lesson-greetings-intro-vocabulary-2', 'lesson-greetings-intro', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-ireum"}'::jsonb, 2),
  ('lesson-greetings-intro-vocabulary-3', 'lesson-greetings-intro', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-nara"}'::jsonb, 3),
  ('lesson-greetings-intro-vocabulary-4', 'lesson-greetings-intro', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-migug"}'::jsonb, 4),
  ('lesson-greetings-intro-vocabulary-5', 'lesson-greetings-intro', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-mannaseo"}'::jsonb, 5),
  ('lesson-greetings-intro-expression-6', 'lesson-greetings-intro', 'expression', '저는 알렉스예요.', 'I''m Alex.', 'jeoneun alekseuyeyo.', null, '{"note":"Swap in your own name."}'::jsonb, 6),
  ('lesson-greetings-intro-expression-7', 'lesson-greetings-intro', 'expression', '저는 미국에서 왔어요.', 'I came from the United States.', 'jeoneun migugeseo wasseoyo.', null, null, 7),
  ('lesson-greetings-intro-expression-8', 'lesson-greetings-intro', 'expression', '이름이 뭐예요?', 'What is your name?', 'ireumi mwoyeyo?', null, null, 8),
  ('lesson-greetings-intro-listening-9', 'lesson-greetings-intro', 'listening', '어느 나라에서 왔어요?', 'Which country are you from?', 'eoneu naraeseo wasseoyo?', null, null, 9),
  ('lesson-greetings-intro-speaking-10', 'lesson-greetings-intro', 'speaking', '안녕하세요. 저는 알렉스예요. 만나서 반가워요.', 'Hello. I''m Alex. Nice to meet you.', 'annyeonghaseyo. jeoneun alekseuyeyo. mannaseo bangawoyo.', null, null, 10),
  ('lesson-greetings-intro-summary-11', 'lesson-greetings-intro', 'summary', null, null, null, null, '{"points":["저는 + name + 예요/이에요 introduces you.","~에서 왔어요 means \"I came from ~\".","Finish with 반가워요 to sound friendly."]}'::jsonb, 11),
  ('lesson-cafe-coffee-introduction-0', 'lesson-cafe-coffee', 'introduction', null, 'Korean cafe ordering is a fixed script. Learn it once and every cafe in the country works the same way.', null, null, '{"heading":"Ordering Coffee"}'::jsonb, 0),
  ('lesson-cafe-coffee-vocabulary-1', 'lesson-cafe-coffee', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-keopi"}'::jsonb, 1),
  ('lesson-cafe-coffee-vocabulary-2', 'lesson-cafe-coffee', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-amerikano"}'::jsonb, 2),
  ('lesson-cafe-coffee-vocabulary-3', 'lesson-cafe-coffee', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-juseyo"}'::jsonb, 3),
  ('lesson-cafe-coffee-vocabulary-4', 'lesson-cafe-coffee', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-hanjan"}'::jsonb, 4),
  ('lesson-cafe-coffee-vocabulary-5', 'lesson-cafe-coffee', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-aiseu"}'::jsonb, 5),
  ('lesson-cafe-coffee-vocabulary-6', 'lesson-cafe-coffee', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-ttatteuthan"}'::jsonb, 6),
  ('lesson-cafe-coffee-vocabulary-7', 'lesson-cafe-coffee', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-teigaut"}'::jsonb, 7),
  ('lesson-cafe-coffee-expression-8', 'lesson-cafe-coffee', 'expression', '아메리카노 한 잔 주세요.', 'One americano, please.', 'amerikano han jan juseyo.', null, null, 8),
  ('lesson-cafe-coffee-expression-9', 'lesson-cafe-coffee', 'expression', '아이스로 주세요.', 'Iced, please.', 'aiseuro juseyo.', null, null, 9),
  ('lesson-cafe-coffee-expression-10', 'lesson-cafe-coffee', 'expression', '테이크아웃 할게요.', 'I''ll take it to go.', 'teikeuaut halgeyo.', null, null, 10),
  ('lesson-cafe-coffee-listening-11', 'lesson-cafe-coffee', 'listening', '드시고 가세요, 아니면 테이크아웃이세요?', 'For here or to go?', 'deusigo gaseyo, animyeon teikeuautiseyo?', null, null, 11),
  ('lesson-cafe-coffee-speaking-12', 'lesson-cafe-coffee', 'speaking', '아이스 아메리카노 한 잔 주세요.', 'One iced americano, please.', 'aiseu amerikano han jan juseyo.', null, null, 12),
  ('lesson-cafe-coffee-summary-13', 'lesson-cafe-coffee', 'summary', null, null, null, null, '{"points":["Anything + 주세요 = \"please give me that\".","한 잔 counts cups.","아이스 / 따뜻한 goes before the drink."]}'::jsonb, 13),
  ('lesson-cafe-water-introduction-0', 'lesson-cafe-water', 'introduction', null, 'Water is usually self-serve in Korea, but 저기요 plus 주세요 gets you anything you need.', null, null, '{"heading":"Asking for Water"}'::jsonb, 0),
  ('lesson-cafe-water-vocabulary-1', 'lesson-cafe-water', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-mul"}'::jsonb, 1),
  ('lesson-cafe-water-vocabulary-2', 'lesson-cafe-water', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-jeogiyo"}'::jsonb, 2),
  ('lesson-cafe-water-vocabulary-3', 'lesson-cafe-water', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-jogeum"}'::jsonb, 3),
  ('lesson-cafe-water-vocabulary-4', 'lesson-cafe-water', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-juseyo"}'::jsonb, 4),
  ('lesson-cafe-water-expression-5', 'lesson-cafe-water', 'expression', '저기요, 물 좀 주세요.', 'Excuse me, some water please.', 'jeogiyo, mul jom juseyo.', null, null, 5),
  ('lesson-cafe-water-expression-6', 'lesson-cafe-water', 'expression', '얼음 주세요.', 'Ice, please.', 'eoreum juseyo.', null, null, 6),
  ('lesson-cafe-water-listening-7', 'lesson-cafe-water', 'listening', '물은 셀프예요.', 'Water is self-serve.', 'mureun selpeuyeyo.', null, null, 7),
  ('lesson-cafe-water-speaking-8', 'lesson-cafe-water', 'speaking', '저기요, 물 좀 주세요.', 'Excuse me, some water please.', 'jeogiyo, mul jom juseyo.', null, null, 8),
  ('lesson-cafe-water-summary-9', 'lesson-cafe-water', 'summary', null, null, null, null, '{"points":["저기요 is how you flag staff politely.","좀 softens a request.","셀프 means self-serve."]}'::jsonb, 9),
  ('lesson-cafe-paying-introduction-0', 'lesson-cafe-paying', 'introduction', null, 'Card is king in Korea. These four lines cover the entire counter exchange.', null, null, '{"heading":"Paying"}'::jsonb, 0),
  ('lesson-cafe-paying-vocabulary-1', 'lesson-cafe-paying', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-eolmayeyo"}'::jsonb, 1),
  ('lesson-cafe-paying-vocabulary-2', 'lesson-cafe-paying', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-kadeu"}'::jsonb, 2),
  ('lesson-cafe-paying-vocabulary-3', 'lesson-cafe-paying', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-hyeongeum"}'::jsonb, 3),
  ('lesson-cafe-paying-vocabulary-4', 'lesson-cafe-paying', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-yeongsujeung"}'::jsonb, 4),
  ('lesson-cafe-paying-expression-5', 'lesson-cafe-paying', 'expression', '얼마예요?', 'How much is it?', 'eolmayeyo?', null, null, 5),
  ('lesson-cafe-paying-expression-6', 'lesson-cafe-paying', 'expression', '카드로 할게요.', 'I''ll pay by card.', 'kadeuro halgeyo.', null, null, 6),
  ('lesson-cafe-paying-expression-7', 'lesson-cafe-paying', 'expression', '영수증 주세요.', 'Receipt, please.', 'yeongsujeung juseyo.', null, null, 7),
  ('lesson-cafe-paying-listening-8', 'lesson-cafe-paying', 'listening', '적립 카드 있으세요?', 'Do you have a points card?', 'jeongnip kadeu isseuseyo?', null, null, 8),
  ('lesson-cafe-paying-speaking-9', 'lesson-cafe-paying', 'speaking', '카드로 할게요. 영수증 주세요.', 'I''ll pay by card. Receipt, please.', 'kadeuro halgeyo. yeongsujeung juseyo.', null, null, 9),
  ('lesson-cafe-paying-summary-10', 'lesson-cafe-paying', 'summary', null, null, null, null, '{"points":["얼마예요? asks any price.","~로 할게요 chooses a payment method.","Staff will ask about 적립 (points) — 괜찮아요 is a fine answer."]}'::jsonb, 10),
  ('lesson-hangul-consonants-introduction-0', 'lesson-hangul-consonants', 'introduction', null, 'Hangul was designed to be learned in a day. Each consonant is a picture of the shape your mouth makes.', null, null, '{"heading":"Hangul Consonants"}'::jsonb, 0),
  ('lesson-hangul-consonants-vocabulary-1', 'lesson-hangul-consonants', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-hangugeo"}'::jsonb, 1),
  ('lesson-hangul-consonants-expression-2', 'lesson-hangul-consonants', 'expression', 'ㄱ', 'g / k — back of the tongue rising', 'g/k', null, null, 2),
  ('lesson-hangul-consonants-expression-3', 'lesson-hangul-consonants', 'expression', 'ㄴ', 'n — tongue tip at the ridge', 'n', null, null, 3),
  ('lesson-hangul-consonants-expression-4', 'lesson-hangul-consonants', 'expression', 'ㅁ', 'm — closed mouth', 'm', null, null, 4),
  ('lesson-hangul-consonants-expression-5', 'lesson-hangul-consonants', 'expression', 'ㅅ', 's — air through a narrow gap', 's', null, null, 5),
  ('lesson-hangul-consonants-listening-6', 'lesson-hangul-consonants', 'listening', '가 나 마 사', 'ga na ma sa', 'ga na ma sa', null, null, 6),
  ('lesson-hangul-consonants-speaking-7', 'lesson-hangul-consonants', 'speaking', '가나다라마바사', 'The Korean alphabet song order.', 'ganadaramabasa', null, null, 7),
  ('lesson-hangul-consonants-summary-8', 'lesson-hangul-consonants', 'summary', null, null, null, null, '{"points":["Consonants are drawn from mouth shapes.","A syllable always starts with a consonant.","ㅇ at the start is silent."]}'::jsonb, 8),
  ('lesson-hangul-vowels-introduction-0', 'lesson-hangul-vowels', 'introduction', null, 'Every vowel is built from three strokes: a vertical line (person), a horizontal line (earth), and a dot (sky).', null, null, '{"heading":"Hangul Vowels"}'::jsonb, 0),
  ('lesson-hangul-vowels-vocabulary-1', 'lesson-hangul-vowels', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-hangugeo"}'::jsonb, 1),
  ('lesson-hangul-vowels-expression-2', 'lesson-hangul-vowels', 'expression', 'ㅏ', 'a — as in "father"', 'a', null, null, 2),
  ('lesson-hangul-vowels-expression-3', 'lesson-hangul-vowels', 'expression', 'ㅓ', 'eo — as in "sun"', 'eo', null, null, 3),
  ('lesson-hangul-vowels-expression-4', 'lesson-hangul-vowels', 'expression', 'ㅗ', 'o — as in "go"', 'o', null, null, 4),
  ('lesson-hangul-vowels-expression-5', 'lesson-hangul-vowels', 'expression', 'ㅜ', 'u — as in "moon"', 'u', null, null, 5),
  ('lesson-hangul-vowels-listening-6', 'lesson-hangul-vowels', 'listening', '아 어 오 우 이', 'a eo o u i', 'a eo o u i', null, null, 6),
  ('lesson-hangul-vowels-speaking-7', 'lesson-hangul-vowels', 'speaking', '아 어 오 우 이', 'Practise the five core vowels.', 'a eo o u i', null, null, 7),
  ('lesson-hangul-vowels-summary-8', 'lesson-hangul-vowels', 'summary', null, null, null, null, '{"points":["Vertical vowels sit to the right of the consonant.","Horizontal vowels sit underneath.","Adding a stroke adds a \"y\" sound: ㅏ → ㅑ."]}'::jsonb, 8),
  ('lesson-numbers-sino-introduction-0', 'lesson-numbers-sino', 'introduction', null, 'Korean has two number systems. Sino-Korean is the one on every price tag and phone number.', null, null, '{"heading":"Numbers for Money"}'::jsonb, 0),
  ('lesson-numbers-sino-vocabulary-1', 'lesson-numbers-sino', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-eolmayeyo"}'::jsonb, 1),
  ('lesson-numbers-sino-vocabulary-2', 'lesson-numbers-sino', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-kadeu"}'::jsonb, 2),
  ('lesson-numbers-sino-expression-3', 'lesson-numbers-sino', 'expression', '일 이 삼 사 오', '1 2 3 4 5', 'il i sam sa o', null, null, 3),
  ('lesson-numbers-sino-expression-4', 'lesson-numbers-sino', 'expression', '육 칠 팔 구 십', '6 7 8 9 10', 'yuk chil pal gu sip', null, null, 4),
  ('lesson-numbers-sino-expression-5', 'lesson-numbers-sino', 'expression', '오천 원이에요.', 'It''s 5,000 won.', 'ocheon wonieyo.', null, null, 5),
  ('lesson-numbers-sino-listening-6', 'lesson-numbers-sino', 'listening', '사천오백 원입니다.', 'That''s 4,500 won.', 'sacheonobaek wonimnida.', null, null, 6),
  ('lesson-numbers-sino-speaking-7', 'lesson-numbers-sino', 'speaking', '이거 얼마예요?', 'How much is this?', 'igeo eolmayeyo?', null, null, 7),
  ('lesson-numbers-sino-summary-8', 'lesson-numbers-sino', 'summary', null, null, null, null, '{"points":["Sino numbers are used for money, dates and phone numbers.","천 = 1,000, 만 = 10,000.","Korean counts in units of 만, not thousands."]}'::jsonb, 8),
  ('lesson-numbers-native-introduction-0', 'lesson-numbers-native', 'introduction', null, 'Native Korean numbers count objects, people, cups and hours — the things you point at.', null, null, '{"heading":"Counting Things"}'::jsonb, 0),
  ('lesson-numbers-native-vocabulary-1', 'lesson-numbers-native', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-hanjan"}'::jsonb, 1),
  ('lesson-numbers-native-vocabulary-2', 'lesson-numbers-native', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-keopi"}'::jsonb, 2),
  ('lesson-numbers-native-expression-3', 'lesson-numbers-native', 'expression', '하나 둘 셋 넷 다섯', '1 2 3 4 5', 'hana dul set net daseot', null, null, 3),
  ('lesson-numbers-native-expression-4', 'lesson-numbers-native', 'expression', '커피 두 잔 주세요.', 'Two coffees, please.', 'keopi du jan juseyo.', null, null, 4),
  ('lesson-numbers-native-listening-5', 'lesson-numbers-native', 'listening', '몇 분이세요?', 'How many people?', 'myeot buniseyo?', null, null, 5),
  ('lesson-numbers-native-speaking-6', 'lesson-numbers-native', 'speaking', '두 명이에요.', 'Two people.', 'du myeongieyo.', null, null, 6),
  ('lesson-numbers-native-summary-7', 'lesson-numbers-native', 'summary', null, null, null, null, '{"points":["하나 becomes 한 before a counter: 한 잔.","잔 for cups, 명 for people, 개 for things.","Use native numbers up to 99."]}'::jsonb, 7),
  ('lesson-food-restaurant-introduction-0', 'lesson-food-restaurant', 'introduction', null, 'Ordering for a table in Korea is a team sport. These lines cover arriving, ordering and paying.', null, null, '{"heading":"At a Restaurant"}'::jsonb, 0),
  ('lesson-food-restaurant-vocabulary-1', 'lesson-food-restaurant', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-menyu"}'::jsonb, 1),
  ('lesson-food-restaurant-vocabulary-2', 'lesson-food-restaurant', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-jumun"}'::jsonb, 2),
  ('lesson-food-restaurant-vocabulary-3', 'lesson-food-restaurant', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-gogi"}'::jsonb, 3),
  ('lesson-food-restaurant-vocabulary-4', 'lesson-food-restaurant', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-masisseoyo"}'::jsonb, 4),
  ('lesson-food-restaurant-vocabulary-5', 'lesson-food-restaurant', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-maewoyo"}'::jsonb, 5),
  ('lesson-food-restaurant-expression-6', 'lesson-food-restaurant', 'expression', '메뉴판 좀 주세요.', 'Could I get a menu?', 'menyupan jom juseyo.', null, null, 6),
  ('lesson-food-restaurant-expression-7', 'lesson-food-restaurant', 'expression', '이거 두 개 주세요.', 'Two of these, please.', 'igeo du gae juseyo.', null, null, 7),
  ('lesson-food-restaurant-expression-8', 'lesson-food-restaurant', 'expression', '계산할게요.', 'I''ll pay now.', 'gyesanhalgeyo.', null, null, 8),
  ('lesson-food-restaurant-listening-9', 'lesson-food-restaurant', 'listening', '주문하시겠어요?', 'Would you like to order?', 'jumunhasigesseoyo?', null, null, 9),
  ('lesson-food-restaurant-speaking-10', 'lesson-food-restaurant', 'speaking', '이거 두 개 주세요. 안 맵게 해 주세요.', 'Two of these please. Not spicy, please.', 'igeo du gae juseyo. an maepge hae juseyo.', null, null, 10),
  ('lesson-food-restaurant-summary-11', 'lesson-food-restaurant', 'summary', null, null, null, null, '{"points":["이거 + counter + 주세요 orders anything you can point at.","계산할게요 asks for the bill.","안 맵게 해 주세요 saves your evening."]}'::jsonb, 11),
  ('lesson-food-convenience-introduction-0', 'lesson-food-convenience', 'introduction', null, 'The 편의점 is a Korean institution. You only need four lines to use one perfectly.', null, null, '{"heading":"Convenience Store"}'::jsonb, 0),
  ('lesson-food-convenience-vocabulary-1', 'lesson-food-convenience', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-pyeonuijeom"}'::jsonb, 1),
  ('lesson-food-convenience-vocabulary-2', 'lesson-food-convenience', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-bongtu"}'::jsonb, 2),
  ('lesson-food-convenience-vocabulary-3', 'lesson-food-convenience', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-yeongsujeung"}'::jsonb, 3),
  ('lesson-food-convenience-vocabulary-4', 'lesson-food-convenience', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-kadeu"}'::jsonb, 4),
  ('lesson-food-convenience-expression-5', 'lesson-food-convenience', 'expression', '봉투 주세요.', 'A bag, please.', 'bongtu juseyo.', null, null, 5),
  ('lesson-food-convenience-expression-6', 'lesson-food-convenience', 'expression', '데워 주세요.', 'Please heat it up.', 'dewo juseyo.', null, null, 6),
  ('lesson-food-convenience-expression-7', 'lesson-food-convenience', 'expression', '괜찮아요.', 'No thanks, I''m fine.', 'gwaenchanayo.', null, null, 7),
  ('lesson-food-convenience-listening-8', 'lesson-food-convenience', 'listening', '봉투 필요하세요?', 'Do you need a bag?', 'bongtu piryohaseyo?', null, null, 8),
  ('lesson-food-convenience-speaking-9', 'lesson-food-convenience', 'speaking', '이거 데워 주세요.', 'Please heat this up.', 'igeo dewo juseyo.', null, null, 9),
  ('lesson-food-convenience-summary-10', 'lesson-food-convenience', 'summary', null, null, null, null, '{"points":["데워 주세요 heats your 도시락.","Bags cost money — say 괜찮아요 to decline.","Most stores have a microwave and hot water for free."]}'::jsonb, 10),
  ('lesson-transport-subway-introduction-0', 'lesson-transport-subway', 'introduction', null, 'Seoul’s subway is signposted in English, but asking a person is still faster when you are lost.', null, null, '{"heading":"Taking the Subway"}'::jsonb, 0),
  ('lesson-transport-subway-vocabulary-1', 'lesson-transport-subway', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-jihacheol"}'::jsonb, 1),
