  ('lesson-transport-subway-vocabulary-3', 'lesson-transport-subway', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-hwanseung"}'::jsonb, 3),
  ('lesson-transport-subway-vocabulary-4', 'lesson-transport-subway', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-chulgu"}'::jsonb, 4),
  ('lesson-transport-subway-vocabulary-5', 'lesson-transport-subway', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-eodiyeyo"}'::jsonb, 5),
  ('lesson-transport-subway-expression-6', 'lesson-transport-subway', 'expression', '강남역 어떻게 가요?', 'How do I get to Gangnam Station?', 'gangnamyeok eotteoke gayo?', null, null, 6),
  ('lesson-transport-subway-expression-7', 'lesson-transport-subway', 'expression', '어디서 환승해요?', 'Where do I transfer?', 'eodiseo hwanseunghaeyo?', null, null, 7),
  ('lesson-transport-subway-expression-8', 'lesson-transport-subway', 'expression', '삼 번 출구에서 만나요.', 'Let''s meet at exit 3.', 'sam beon chulguesseo mannayo.', null, null, 8),
  ('lesson-transport-subway-listening-9', 'lesson-transport-subway', 'listening', '이번 역은 홍대입구역입니다.', 'This stop is Hongdae Ipgu Station.', 'ibeon yeogeun hongdaeipguyeogimnida.', null, null, 9),
  ('lesson-transport-subway-speaking-10', 'lesson-transport-subway', 'speaking', '홍대입구역 어떻게 가요?', 'How do I get to Hongdae Ipgu Station?', 'hongdaeipguyeok eotteoke gayo?', null, null, 10),
  ('lesson-transport-subway-summary-11', 'lesson-transport-subway', 'summary', null, null, null, null, '{"points":["~ 어떻게 가요? asks for directions anywhere.","Exits are numbered — Koreans meet at exit numbers.","환승 is the transfer station."]}'::jsonb, 11),
  ('lesson-transport-taxi-introduction-0', 'lesson-transport-taxi', 'introduction', null, 'Three lines will get you into a taxi, to your destination, and back out again.', null, null, '{"heading":"Taking a Taxi"}'::jsonb, 0),
  ('lesson-transport-taxi-vocabulary-1', 'lesson-transport-taxi', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-taeksi"}'::jsonb, 1),
  ('lesson-transport-taxi-vocabulary-2', 'lesson-transport-taxi', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-yeok"}'::jsonb, 2),
  ('lesson-transport-taxi-vocabulary-3', 'lesson-transport-taxi', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-yeogiyo-stop"}'::jsonb, 3),
  ('lesson-transport-taxi-expression-4', 'lesson-transport-taxi', 'expression', '강남역으로 가 주세요.', 'To Gangnam Station, please.', 'gangnamyeogeuro ga juseyo.', null, null, 4),
  ('lesson-transport-taxi-expression-5', 'lesson-transport-taxi', 'expression', '여기서 세워 주세요.', 'Please stop here.', 'yeogiseo sewo juseyo.', null, null, 5),
  ('lesson-transport-taxi-expression-6', 'lesson-transport-taxi', 'expression', '카드 되나요?', 'Can I pay by card?', 'kadeu doenayo?', null, null, 6),
  ('lesson-transport-taxi-listening-7', 'lesson-transport-taxi', 'listening', '어디로 모실까요?', 'Where shall I take you?', 'eodiro mosilkkayo?', null, null, 7),
  ('lesson-transport-taxi-speaking-8', 'lesson-transport-taxi', 'speaking', '이 주소로 가 주세요.', 'Please go to this address.', 'i jusoro ga juseyo.', null, null, 8),
  ('lesson-transport-taxi-summary-9', 'lesson-transport-taxi', 'summary', null, null, null, null, '{"points":["목적지 + 으로/로 가 주세요 sets the destination.","여기서 세워 주세요 stops the car.","되나요? asks \"is that possible?\" about anything."]}'::jsonb, 9),
  ('lesson-shopping-sizes-introduction-0', 'lesson-shopping-sizes', 'introduction', null, 'Korean shops are hands-on. Ask to try things and to swap sizes without any awkwardness.', null, null, '{"heading":"Sizes & Colors"}'::jsonb, 0),
  ('lesson-shopping-sizes-vocabulary-1', 'lesson-shopping-sizes', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-halin"}'::jsonb, 1),
  ('lesson-shopping-sizes-vocabulary-2', 'lesson-shopping-sizes', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-eolmayeyo"}'::jsonb, 2),
  ('lesson-shopping-sizes-vocabulary-3', 'lesson-shopping-sizes', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-kadeu"}'::jsonb, 3),
  ('lesson-shopping-sizes-expression-4', 'lesson-shopping-sizes', 'expression', '입어 봐도 돼요?', 'Can I try it on?', 'ibeo bwado dwaeyo?', null, null, 4),
  ('lesson-shopping-sizes-expression-5', 'lesson-shopping-sizes', 'expression', '더 큰 사이즈 있어요?', 'Do you have a bigger size?', 'deo keun saijeu isseoyo?', null, null, 5),
  ('lesson-shopping-sizes-expression-6', 'lesson-shopping-sizes', 'expression', '다른 색 있어요?', 'Do you have another colour?', 'dareun saek isseoyo?', null, null, 6),
  ('lesson-shopping-sizes-listening-7', 'lesson-shopping-sizes', 'listening', '이거 새 상품이에요.', 'This one is brand new.', 'igeo sae sangpumieyo.', null, null, 7),
  ('lesson-shopping-sizes-speaking-8', 'lesson-shopping-sizes', 'speaking', '더 큰 사이즈 있어요?', 'Do you have a bigger size?', 'deo keun saijeu isseoyo?', null, null, 8),
  ('lesson-shopping-sizes-summary-9', 'lesson-shopping-sizes', 'summary', null, null, null, null, '{"points":["~ 있어요? asks if a shop has something.","~해도 돼요? asks permission.","더 + adjective = \"more ~\"."]}'::jsonb, 9),
  ('lesson-conversation-smalltalk-introduction-0', 'lesson-conversation-smalltalk', 'introduction', null, 'Korean small talk runs on food, weather and weekends. Three questions keep any conversation alive.', null, null, '{"heading":"Small Talk"}'::jsonb, 0),
  ('lesson-conversation-smalltalk-vocabulary-1', 'lesson-conversation-smalltalk', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-oneul"}'::jsonb, 1),
  ('lesson-conversation-smalltalk-vocabulary-2', 'lesson-conversation-smalltalk', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-bap"}'::jsonb, 2),
  ('lesson-conversation-smalltalk-vocabulary-3', 'lesson-conversation-smalltalk', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-jaemiisseoyo"}'::jsonb, 3),
  ('lesson-conversation-smalltalk-vocabulary-4', 'lesson-conversation-smalltalk', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-bappayo"}'::jsonb, 4),
  ('lesson-conversation-smalltalk-expression-5', 'lesson-conversation-smalltalk', 'expression', '밥 먹었어요?', 'Have you eaten?', 'bap meogeosseoyo?', null, '{"note":"This is a greeting, not a dinner invitation."}'::jsonb, 5),
  ('lesson-conversation-smalltalk-expression-6', 'lesson-conversation-smalltalk', 'expression', '주말에 뭐 했어요?', 'What did you do on the weekend?', 'jumare mwo haesseoyo?', null, null, 6),
  ('lesson-conversation-smalltalk-expression-7', 'lesson-conversation-smalltalk', 'expression', '요즘 어때요?', 'How have you been lately?', 'yojeum eottaeyo?', null, null, 7),
  ('lesson-conversation-smalltalk-listening-8', 'lesson-conversation-smalltalk', 'listening', '요즘 너무 바빠요.', 'I''m so busy lately.', 'yojeum neomu bappayo.', null, null, 8),
  ('lesson-conversation-smalltalk-speaking-9', 'lesson-conversation-smalltalk', 'speaking', '주말에 뭐 했어요?', 'What did you do on the weekend?', 'jumare mwo haesseoyo?', null, null, 9),
  ('lesson-conversation-smalltalk-summary-10', 'lesson-conversation-smalltalk', 'summary', null, null, null, null, '{"points":["밥 먹었어요? means \"how are you\".","뭐 했어요? asks what someone did.","어때요? asks for an opinion about anything."]}'::jsonb, 10),
  ('lesson-living-delivery-introduction-0', 'lesson-living-delivery', 'introduction', null, 'Korean delivery is fast and phone-based. These lines handle the driver, the app and the front desk.', null, null, '{"heading":"Package Delivery"}'::jsonb, 0),
  ('lesson-living-delivery-vocabulary-1', 'lesson-living-delivery', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-baedal"}'::jsonb, 1),
  ('lesson-living-delivery-vocabulary-2', 'lesson-living-delivery', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-pojang"}'::jsonb, 2),
  ('lesson-living-delivery-vocabulary-3', 'lesson-living-delivery', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-gwaenchanayo"}'::jsonb, 3),
  ('lesson-living-delivery-expression-4', 'lesson-living-delivery', 'expression', '문 앞에 놓아 주세요.', 'Please leave it at the door.', 'mun ape noa juseyo.', null, null, 4),
  ('lesson-living-delivery-expression-5', 'lesson-living-delivery', 'expression', '택배 왔어요?', 'Did the package arrive?', 'taekbae wasseoyo?', null, null, 5),
  ('lesson-living-delivery-expression-6', 'lesson-living-delivery', 'expression', '경비실에 맡겨 주세요.', 'Please leave it with the security desk.', 'gyeongbisire matgyeo juseyo.', null, null, 6),
  ('lesson-living-delivery-listening-7', 'lesson-living-delivery', 'listening', '택배입니다. 문 앞에 뒀어요.', 'Delivery. I left it at the door.', 'taekbaeimnida. mun ape dwosseoyo.', null, null, 7),
  ('lesson-living-delivery-speaking-8', 'lesson-living-delivery', 'speaking', '문 앞에 놓아 주세요.', 'Please leave it at the door.', 'mun ape noa juseyo.', null, null, 8),
  ('lesson-living-delivery-summary-9', 'lesson-living-delivery', 'summary', null, null, null, null, '{"points":["문 앞 = in front of the door.","경비실 is the building security office.","~아/어 주세요 politely asks for a favour."]}'::jsonb, 9),
  ('lesson-travel-airport-introduction-0', 'lesson-travel-airport', 'introduction', null, 'From immigration to the airport bus, this is the Korean you need in your first hour in the country.', null, null, '{"heading":"At the Airport"}'::jsonb, 0),
  ('lesson-travel-airport-vocabulary-1', 'lesson-travel-airport', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-beoseu"}'::jsonb, 1),
  ('lesson-travel-airport-vocabulary-2', 'lesson-travel-airport', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-eodiyeyo"}'::jsonb, 2),
  ('lesson-travel-airport-vocabulary-3', 'lesson-travel-airport', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-kadeu"}'::jsonb, 3),
  ('lesson-travel-airport-expression-4', 'lesson-travel-airport', 'expression', '여행으로 왔어요.', 'I''m here for travel.', 'yeohaengeuro wasseoyo.', null, null, 4),
  ('lesson-travel-airport-expression-5', 'lesson-travel-airport', 'expression', '티머니 카드 주세요.', 'A T-money card, please.', 'timeoni kadeu juseyo.', null, null, 5),
  ('lesson-travel-airport-expression-6', 'lesson-travel-airport', 'expression', '공항버스 어디서 타요?', 'Where do I catch the airport bus?', 'gonghangbeoseu eodiseo tayo?', null, null, 6),
  ('lesson-travel-airport-listening-7', 'lesson-travel-airport', 'listening', '방문 목적이 뭐예요?', 'What is the purpose of your visit?', 'bangmun mokjeogi mwoyeyo?', null, null, 7),
  ('lesson-travel-airport-speaking-8', 'lesson-travel-airport', 'speaking', '공항버스 어디서 타요?', 'Where do I catch the airport bus?', 'gonghangbeoseu eodiseo tayo?', null, null, 8),
  ('lesson-travel-airport-summary-9', 'lesson-travel-airport', 'summary', null, null, null, null, '{"points":["~으로 왔어요 states your purpose.","어디서 타요? asks where to board.","T-money works on every bus, subway and most taxis."]}'::jsonb, 9),
  ('lesson-work-greetings-introduction-0', 'lesson-work-greetings', 'introduction', null, 'Korean offices run on a handful of set phrases. Using them correctly signals that you understand the culture.', null, null, '{"heading":"Office Greetings"}'::jsonb, 0),
  ('lesson-work-greetings-vocabulary-1', 'lesson-work-greetings', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-hoesa"}'::jsonb, 1),
  ('lesson-work-greetings-vocabulary-2', 'lesson-work-greetings', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-sugohasyeotseumnida"}'::jsonb, 2),
  ('lesson-work-greetings-vocabulary-3', 'lesson-work-greetings', 'vocabulary', null, null, null, null, '{"vocabularyId":"v-hoeui"}'::jsonb, 3),
  ('lesson-work-greetings-expression-4', 'lesson-work-greetings', 'expression', '안녕하십니까.', 'Good morning (formal).', 'annyeonghasimnikka.', null, null, 4),
  ('lesson-work-greetings-expression-5', 'lesson-work-greetings', 'expression', '수고하셨습니다.', 'Good work today.', 'sugohasyeotseumnida.', null, '{"note":"Say it to peers and juniors, not to your boss."}'::jsonb, 5),
  ('lesson-work-greetings-expression-6', 'lesson-work-greetings', 'expression', '먼저 들어가 보겠습니다.', 'I''ll head out first.', 'meonjeo deureoga bogesseumnida.', null, null, 6),
  ('lesson-work-greetings-listening-7', 'lesson-work-greetings', 'listening', '회의 세 시에 시작합니다.', 'The meeting starts at 3.', 'hoeui se sie sijakhamnida.', null, null, 7),
  ('lesson-work-greetings-speaking-8', 'lesson-work-greetings', 'speaking', '수고하셨습니다. 먼저 들어가 보겠습니다.', 'Good work today. I''ll head out first.', 'sugohasyeotseumnida. meonjeo deureoga bogesseumnida.', null, null, 8),
  ('lesson-work-greetings-summary-9', 'lesson-work-greetings', 'summary', null, null, null, null, '{"points":["~습니다 is the formal business ending.","수고하셨습니다 closes the workday.","Leaving before others needs a polite phrase."]}'::jsonb, 9)
