values
  ('q-hello-1', 'lesson-greetings-hello', 'multiple_choice_ko_en', 'What does 안녕하세요 mean?', '안녕하세요', 'Hello', ARRAY['Hello', 'Thank you', 'Goodbye', 'Sorry']::text[], null),
  ('q-hello-2', 'lesson-greetings-hello', 'multiple_choice_en_ko', 'How do you say goodbye to someone who is leaving?', null, '안녕히 가세요', ARRAY['안녕히 가세요', '안녕히 계세요', '감사합니다', '반가워요']::text[], null),
  ('q-hello-3', 'lesson-greetings-hello', 'true_false', '안녕하세요 can be used in the morning and the evening.', null, 'True', ARRAY['True', 'False']::text[], null),
  ('q-hello-4', 'lesson-greetings-hello', 'sentence_ordering', 'Put the sentence in the right order.', 'Nice to meet you.', '만나서 반가워요', ARRAY['만나서', '반가워요']::text[], null),
  ('q-yesno-1', 'lesson-greetings-yesno', 'multiple_choice_ko_en', 'What does 아니요 mean?', '아니요', 'No', ARRAY['No', 'Yes', 'Maybe', 'Please']::text[], null),
  ('q-yesno-2', 'lesson-greetings-yesno', 'fill_in_the_blank', 'Complete: ___, 괜찮아요. ("No, I''m fine.")', '___, 괜찮아요.', '아니요', ARRAY['아니요', '네', '주세요', '감사']::text[], null),
  ('q-thanks-1', 'lesson-greetings-thanks', 'multiple_choice_en_ko', 'How do you say "thank you" formally?', null, '감사합니다', ARRAY['감사합니다', '죄송합니다', '천만에요', '괜찮아요']::text[], null),
  ('q-thanks-2', 'lesson-greetings-thanks', 'multiple_choice_ko_en', 'What does 죄송합니다 mean?', '죄송합니다', 'I am sorry', ARRAY['I am sorry', 'Thank you', 'You are welcome', 'Excuse me']::text[], null),
  ('q-thanks-3', 'lesson-greetings-thanks', 'word_matching', 'Match the Korean to its meaning.', null, '천만에요', ARRAY['천만에요', '감사합니다', '죄송합니다', '반가워요']::text[], '{"matchTarget":"You''re welcome"}'::jsonb),
  ('q-intro-1', 'lesson-greetings-intro', 'multiple_choice_ko_en', 'What does 저는 미국에서 왔어요 mean?', '저는 미국에서 왔어요.', 'I came from the United States', ARRAY['I came from the United States', 'I am going to America', 'I live in Korea', 'I like America']::text[], null),
  ('q-intro-2', 'lesson-greetings-intro', 'fill_in_the_blank', 'Complete: 이름이 ___? ("What is your name?")', '이름이 ___?', '뭐예요', ARRAY['뭐예요', '주세요', '왔어요', '괜찮아요']::text[], null),
  ('q-intro-3', 'lesson-greetings-intro', 'sentence_ordering', 'Build: "I am Alex."', 'I am Alex.', '저는 알렉스예요', ARRAY['저는', '알렉스예요']::text[], null),
  ('q-coffee-1', 'lesson-cafe-coffee', 'multiple_choice_en_ko', 'How do you order one americano?', null, '아메리카노 한 잔 주세요', ARRAY['아메리카노 한 잔 주세요', '아메리카노 얼마예요?', '물 좀 주세요', '카드로 할게요']::text[], null),
  ('q-coffee-2', 'lesson-cafe-coffee', 'multiple_choice_ko_en', 'What does 주세요 mean?', '주세요', 'Please give me', ARRAY['Please give me', 'Thank you', 'How much', 'I am sorry']::text[], null),
  ('q-coffee-3', 'lesson-cafe-coffee', 'listening', 'What did you hear?', '아이스 아메리카노 주세요.', 'An iced americano, please', ARRAY['An iced americano, please', 'A hot latte, please', 'Water, please', 'The receipt, please']::text[], null),
  ('q-coffee-4', 'lesson-cafe-coffee', 'sentence_ordering', 'Build: "One americano, please."', 'One americano, please.', '아메리카노 한 잔 주세요', ARRAY['아메리카노', '한 잔', '주세요']::text[], null),
  ('q-coffee-5', 'lesson-cafe-coffee', 'true_false', '테이크아웃 means you will drink it in the cafe.', null, 'False', ARRAY['True', 'False']::text[], null),
  ('q-water-1', 'lesson-cafe-water', 'multiple_choice_ko_en', 'What does 저기요 mean?', '저기요', 'Excuse me', ARRAY['Excuse me', 'Over there', 'Goodbye', 'Please wait']::text[], null),
  ('q-water-2', 'lesson-cafe-water', 'fill_in_the_blank', 'Complete: 물 좀 ___. ("Some water, please.")', '물 좀 ___.', '주세요', ARRAY['주세요', '왔어요', '괜찮아요', '얼마예요']::text[], null),
  ('q-paying-1', 'lesson-cafe-paying', 'multiple_choice_ko_en', 'What does 얼마예요? mean?', '얼마예요?', 'How much is it?', ARRAY['How much is it?', 'Where is it?', 'What is it?', 'Who is it?']::text[], null),
  ('q-paying-2', 'lesson-cafe-paying', 'multiple_choice_en_ko', 'How do you ask for a receipt?', null, '영수증 주세요', ARRAY['영수증 주세요', '봉투 주세요', '카드 되나요?', '얼마예요?']::text[], null),
  ('q-paying-3', 'lesson-cafe-paying', 'word_matching', 'Match the Korean to its meaning.', null, '현금', ARRAY['현금', '카드', '영수증', '봉투']::text[], '{"matchTarget":"Cash"}'::jsonb),
  ('q-hangul-1', 'lesson-hangul-consonants', 'multiple_choice_ko_en', 'How is ㄱ pronounced?', 'ㄱ', 'g / k', ARRAY['g / k', 'n', 'm', 's']::text[], null),
  ('q-hangul-2', 'lesson-hangul-consonants', 'multiple_choice_ko_en', 'How do you read 가?', '가', 'ga', ARRAY['ga', 'na', 'ma', 'sa']::text[], null),
  ('q-hangul-3', 'lesson-hangul-vowels', 'multiple_choice_ko_en', 'How is ㅗ pronounced?', 'ㅗ', 'o', ARRAY['o', 'a', 'u', 'eo']::text[], null),
  ('q-hangul-4', 'lesson-hangul-vowels', 'true_false', 'Horizontal vowels like ㅗ are written under the consonant.', null, 'True', ARRAY['True', 'False']::text[], null),
  ('q-numbers-1', 'lesson-numbers-sino', 'multiple_choice_ko_en', 'What number is 오?', '오', '5', ARRAY['5', '3', '7', '10']::text[], null),
  ('q-numbers-2', 'lesson-numbers-native', 'fill_in_the_blank', 'Complete: 커피 ___ 잔 주세요. ("Two coffees, please.")', '커피 ___ 잔 주세요.', '두', ARRAY['두', '이', '둘', '다섯']::text[], null),
  ('q-restaurant-1', 'lesson-food-restaurant', 'multiple_choice_ko_en', 'What does 주문하시겠어요? mean?', '주문하시겠어요?', 'Would you like to order?', ARRAY['Would you like to order?', 'Is it spicy?', 'How many people?', 'Do you need a bag?']::text[], null),
  ('q-restaurant-2', 'lesson-food-restaurant', 'multiple_choice_en_ko', 'How do you ask for the bill?', null, '계산할게요', ARRAY['계산할게요', '주문할게요', '데워 주세요', '포장해 주세요']::text[], null),
  ('q-convenience-1', 'lesson-food-convenience', 'multiple_choice_ko_en', 'What does 데워 주세요 mean?', '데워 주세요', 'Please heat it up', ARRAY['Please heat it up', 'Please pack it', 'Please give me a bag', 'Please stop here']::text[], null),
